function criarCardCurso(r){return`\n    <article class="curso">\n      <h3>${r.titulo}</h3>\n      <p>${r.descricao}</p>\n      <button type="button">Começar</button>\n    </article>\n  `}const cursos=[{titulo:"Primeiros passos no digital",descricao:"Aprenda a utilizar ferramentas e recursos digitais de forma simples e prática."},{titulo:"Internet e segurança",descricao:"Aprenda a navegar pela internet com mais segurança e identificar possíveis riscos."},{titulo:"Ferramentas profissionais",descricao:"Conheça ferramentas digitais que podem ajudar no desenvolvimento profissional."},{titulo:"Currículo e empregabilidade",descricao:"Aprenda a criar um currículo e apresentar suas experiências de forma profissional."},{titulo:"Como buscar oportunidades",descricao:"Aprenda a utilizar plataformas digitais para encontrar oportunidades de trabalho."},{titulo:"Preparação para entrevistas",descricao:"Desenvolva estratégias para se preparar melhor para entrevistas de emprego."}];export function renderizarCursos(){const r=document.querySelector("#listaCursos");r&&(r.innerHTML=cursos.map(criarCardCurso).join(""))}